CREATE TABLE finance_exchange_rate (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,from_currency CHAR(3) NOT NULL,to_currency CHAR(3) NOT NULL,rate NUMERIC(28,12) NOT NULL,effective_at TIMESTAMPTZ NOT NULL,provider VARCHAR(128),source VARCHAR(32) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(rate>0),CHECK(source IN ('MANUAL','EXTERNAL_PROVIDER','IMPORTED')),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id)); CREATE INDEX idx_finance_exchange_rate ON finance_exchange_rate(ledger_id,from_currency,to_currency,effective_at DESC);
